mapper.select:

WHERE a.workspace_id=#{workspaceId}
AND a.owner_id=#{ownerId}
AND a.program_id=#{programId}
ORDER BY a.application_round DESC LIMIT 1 FOR UPDATE

mapper.sql:
WHERE a.workspace_id=#{workspaceId}

  AND a.owner_id=#{ownerId}


  AND EXISTS(SELECT 1
  FROM staff_assignment s
  WHERE s.application_id=a.id
  AND s.staff_id=#{staffId})


  AND a.status=#{status}


  AND (a.business_name LIKE CONCAT('%',#{keyword},'%')
  OR a.receipt_no LIKE CONCAT('%',#{keyword},'%'))


  AND a.submitted_at >= #{from}


  AND a.submitted_at < #{until}

mapper.select:


ORDER BY a.updated_at DESC,a.id DESC
LIMIT #{limit}
OFFSET #{offset}

SELECT a.status,COUNT(*) AS total FROM application a
WHERE a.workspace_id=#{workspaceId} AND a.owner_id=#{ownerId}
GROUP BY a.status

SELECT COUNT(*)
FROM staff_assignment
WHERE application_id=#{applicationId}
AND staff_id=#{staffId}

mapper.update:
UPDATE application
SET address=#{address},business_type=#{businessType},business_item=#{businessItem},self_contribution=#{selfContribution},business_name=#{businessName},business_no=#{businessNo},representative=#{representative},opened_on=#{openedOn},phone=#{phone},plan_text=#{planText},requested_amount=#{requestedAmount},receipt_no=#{receiptNo},status=#{status},submitted_at=#{submittedAt},updated_at=UTC_TIMESTAMP(6),version=version+1
WHERE id=#{id}
AND version=#{version}

mapper.insert:
INSERT INTO application_revision(application_id,revision_no,snapshot,submitted_by) SELECT #{applicationId},COALESCE(MAX(revision_no),0)+1,#{snapshot},#{submittedBy}
FROM application_revision
WHERE application_id=#{applicationId}

mapper.select:
SELECT revision_id
FROM submission_command
WHERE application_id=#{applicationId}
AND idempotency_key=#{key}
AND payload_hash=#{hash}

SELECT COUNT(*)
FROM submission_command
WHERE application_id=#{applicationId}
AND idempotency_key=#{key}

SELECT *
FROM application_revision
WHERE application_id=#{applicationId}
AND id=#{revisionId}
